(defn grants-sql
  "Explicit trusted-server role; never grant this role to browser connections."
  []
  (str
   "DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='finfolk_directory') THEN CREATE ROLE finfolk_directory NOLOGIN NOINHERIT; END IF; END $$;\n"
   "GRANT USAGE ON SCHEMA finfolk,finfolk_rpc TO finfolk_directory;\n"
   "GRANT SELECT,INSERT,UPDATE ON finfolk.\"DirectoryRun\",finfolk.\"DirectoryListing\",finfolk.\"DirectoryReport\",finfolk.\"Access\",finfolk.\"AccessRole\",finfolk.\"AccessRequest\",finfolk.\"AccessInviteExternal\",finfolk.\"Rev\",finfolk.\"RevLog\",finfolk.\"Audit\",finfolk.\"AuditLog\",finfolk.\"Social\",finfolk.\"Op\",finfolk.\"User\",finfolk.\"Activity\",finfolk.\"ActivityLog\" TO finfolk_directory;\n"
   "GRANT SELECT(key) ON finfolk.\"DatabaseRelease\" TO finfolk_directory;\n"
   "GRANT EXECUTE ON FUNCTION finfolk.auth_uid(),finfolk.as_jsonb(jsonb),finfolk.op_fn(text,uuid,jsonb),finfolk.insert_base_addons(text,uuid,jsonb,jsonb),finfolk.ret_social_url(text),finfolk.ret_social_urls(jsonb),finfolk_rpc.insert_user(uuid,jsonb,jsonb),finfolk_rpc.insert_directory_listing(jsonb,jsonb),finfolk_rpc.ret_directory_public(uuid),finfolk_rpc.account_portrait(text),finfolk_rpc.account_link(text,text),finfolk_rpc.directory_socials(jsonb),finfolk_rpc.directory_document(jsonb),finfolk_rpc.directory_owner_row(finfolk.\"DirectoryListing\"),finfolk_rpc.directory_operation(text,jsonb) TO finfolk_directory;\n"))
